#include <cstdio>
#include <vector>
using namespace std;

int main() {
    int n;
    while (scanf("%d", &n), n) {
        int m;
        scanf("%d", &m);
        vector<long long> num(n); // Use vector for dynamic sizing
        for (int i = 0; i < n; i++)
            scanf("%lld", &num[i]);

        long long ans = 0, current_sum = 0;

        for (int i = 0; i < m && i < n; i++)
            current_sum += num[i];

        ans = current_sum;

        for (int i = m; i < n; i++) {
            current_sum += num[i] - num[i - m];
            if (current_sum > ans)
                ans = current_sum;
        }

        printf("%lld\n", ans);
    }
    return 0;
}

