#include <cstdio>
#include <algorithm>
#include <numeric> // Include for std::accumulate
using namespace std;

int main() {
    int n;
    while (scanf("%d", &n), n) {
        int m;
        scanf("%d", &m);
        long long* num = new long long[n]; // Dynamic memory allocation
        for (int i = 0; i < n; i++)
            scanf("%lld", &num[i]);

        long long ans = 0;

        // Simplified sum calculation using std::accumulate
        long long current_sum = accumulate(num, num + min(m, n), 0LL);

        ans = current_sum;

        for (int i = m; i < n; i++) {
            current_sum += num[i] - num[i - m];
            ans = max(ans, current_sum);
        }

        printf("%lld\n", ans);
        delete[] num; // Free dynamically allocated memory
    }
    return 0;
}

